[metadata] {"type": "create", "filePath": "/app/src/main/java/com/example/contact/MessageStore.java", "content": "package com.example.contact;

import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;

import com.vaadin.flow.server.VaadinSession;

/**
 * Keeps the sent messages around for longer than a single visit to the contact
 * view. The store lives in the {@link VaadinSession}, so navigating away from
 * the view and back again still shows everything that has been sent.
 */
public class MessageStore implements Serializable {

    private static final String KEY = MessageStore.class.getName();

    /** Used only if there is no session to hang the store on. */
    private static final MessageStore FALLBACK = new MessageStore();

    private final List<Message> messages = new ArrayList<>();

    public static MessageStore current() {
        try {
            VaadinSession session = VaadinSession.getCurrent();
            if (session != null) {
                MessageStore store = (MessageStore) session.getAttribute(KEY);
                if (store == null) {
                    store = new MessageStore();
                    session.setAttribute(KEY, store);
                }
                return store;
            }
        } catch (RuntimeException e) {
            // No session available (or not locked) - fall through.
        }
        return FALLBACK;
    }

    /** Adds a message so that it becomes the first one in {@link #all()}. */
    public synchronized void add(Message message) {
        messages.add(0, message);
    }

    /** The messages sent so far, newest first. */
    public synchronized List<Message> all() {
        return new ArrayList<>(messages);
    }
}
