    private static final int MAX_MESSAGE_LENGTH = 500;

    private final TextField name = new TextField("Name");
    private final EmailField email = new EmailField("Email");
    private final TextField phone = new TextField("Phone");
    private final TextArea message = new TextArea("Message");
    private final Button send = new Button("Send");

    private final Grid<Message> messages = new Grid<>();

    private final MessageStore store = MessageStore.current();

    public ContactView() {
        setSizeFull();

        add(new H1("Contact"));
        add(new RouterLink("About", AboutView.class));

        for (var field : new com.vaadin.flow.component.textfield.TextFieldBase[] { name, email, phone, message }) {
            // Validation happens when Send is pressed, and only then.
            field.setManualValidation(true);
            field.setValueChangeMode(ValueChangeMode.EAGER);
            field.addValueChangeListener(e -> send.setEnabled(true));
        }

        send.addClickListener(e -> send());
        send.addClickShortcut(Key.ENTER);
        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);

        FormLayout form = new FormLayout(name, email, phone, message, send);
        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1),
                new FormLayout.ResponsiveStep("30em", 2));
        form.setColspan(message, 2);
        add(form);

        messages.addColumn(Message::name).setHeader("Name").setAutoWidth(true);
        messages.addColumn(Message::message).setHeader("Message").setFlexGrow(1);
        refreshGrid();
        add(messages);
    }

    private void send() {
        if (!send.isEnabled() || !validate()) {
            return;
        }

        store.add(new Message(name.getValue().trim(), value(email), value(phone),
                message.getValue().trim()));
        refreshGrid();

        name.clear();
        email.clear();
        phone.clear();
        message.clear();
        clearErrors();

        // Enabled again as soon as the user edits any field.
        send.setEnabled(false);

        Notification.show("Message sent");
    }

