+        send().click();
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+
+        GridElement grid = GridElement.get(page);
+        grid.assertRowCount(1);
+        assertTrue(grid.findCell(0, 0).orElseThrow().getCellContentLocator().textContent().contains("Alice"));
+        assertTrue(grid.findCell(0, 1).orElseThrow().getCellContentLocator().textContent()
+                .contains("Hello there"));
+
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", message().getValue());
+        send().assertDisabled();
+
+        name().setValue("B");
+        send().assertEnabled();
+    }
+
+    @Test
+    void enterSendsTheForm() {
+        name().setValue("Alice");
+        phone().setValue("040 1234567");
+        message().setValue("Sent with Enter");
+        message().getInputLocator().press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        GridElement.get(page).assertRowCount(1);
+    }
+
+    @Test
+    void emptyFormLeavesWithoutAsking() {
+        clickLink("About");
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertEquals(0, page.locator("vaadin-dialog[opened]").count(),
+                "No dialog is expected");
+    }
+
+    @Test
+    void dirtyFormAsksBeforeLeaving() {
+        name().setValue("Alice");
+        clickLink("About");
+
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Keep editing").click();
+
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(page.locator("vaadin-dialog[opened]")).hasCount(0);
+        assertEquals("Alice", name().getValue());
+
+        clickLink("About");
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+
+        assertThat(page.locator("h1")).hasText("About");
+    }
+
+    @Test
+    void messagesSurviveNavigation() {
+        name().setValue("Alice");
+        phone().setValue("040 1234567");
+        message().setValue("First");
+        send().click();
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+
+        clickLink("About");
+        assertThat(page.locator("h1")).hasText("About");
+
+        clickLink("Contact");
+        assertThat(page.locator("h1")).hasText("Contact");
+
+        GridElement grid = GridElement.get(page);
+        grid.assertRowCount(1);
+        assertTrue(grid.findCell(0, 1).orElseThrow().getCellContentLocator()
+                .textContent().contains("First"));
+    }
+
+    /** Clicks a router link once the client has caught up with what was typed. */
+    private void clickLink(String text) {
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+        page.getByRole(AriaRole.LINK,
+                new Page.GetByRoleOptions().setName(text).setExact(true)).click();
+    }
+}
