+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name() {
+        return find(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return find(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextField phone() {
+        return find(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea message() {
+        return find(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return find(Button.class).withText("Send").single();
+    }
+
+    private Grid<?> grid() {
+        return find(Grid.class).single();
+    }
+
+    private void fill(String nameValue, String emailValue, String phoneValue,
+            String messageValue) {
+        test(name()).setValue(nameValue);
+        test(email()).setValue(emailValue);
+        test(phone()).setValue(phoneValue);
+        test(message()).setValue(messageValue);
+    }
+
+    @Test
+    void contactView_showsHeadingLinkFormAndGrid() {
+        navigate("contact", ContactView.class);
+
+        assertEquals("Contact", find(H1.class).single().getText());
+        RouterLink about = find(RouterLink.class).withText("About").single();
+        assertEquals("about", test(about).getPath());
+
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled(), "Send must be enabled on an empty form");
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void aboutView_showsHeading() {
+        navigate("about", AboutView.class);
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void emptyForm_reportsNameEmailAndMessage() {
+        navigate("contact", ContactView.class);
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number",
+                email().getErrorMessage());
+        assertFalse(phone().isInvalid());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+
+        assertEquals(0, find(Notification.class).all().size());
+        assertEquals(0, test(grid()).size());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void invalidEmail_isReported() {
+        navigate("contact", ContactView.class);
+        fill("Alice", "not-an-email", "", "Hello");
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+        assertEquals(0, test(grid()).size());
+        // Nothing is lost
+        assertEquals("Alice", name().getValue());
+        assertEquals("Hello", message().getValue());
+    }
+
+    @Test
+    void phoneOnly_isEnough() {
+        navigate("contact", ContactView.class);
+        fill("Alice", "", "+358 40 123 4567", "Hello");
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void tooLongMessage_isReported() {
+        navigate("contact", ContactView.class);
+        fill("Alice", "alice@example.com", "", "x".repeat(501));
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters",
+                message().getErrorMessage());
+        assertEquals(0, test(grid()).size());
+
+        // 500 characters is fine
+        test(message()).setValue("x".repeat(500));
+        test(send()).click();
+        assertFalse(message().isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void blankNameCountsAsMissing() {
+        navigate("contact", ContactView.class);
+        fill("   ", "alice@example.com", "", "Hello");
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+    }
+
+    @Test
+    void validForm_sendsAndResets() {
+        navigate("contact", ContactView.class);
+        fill("Alice", "alice@example.com", "", "Hello there");
+        test(send()).click();
+
+        assertTrue(find(Notification.class).all().stream()
+                .anyMatch(n -> test(n).getText().contains("Message sent")),
+                "A 'Message sent' notification is expected");
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Alice", test(grid()).getCellText(0, 0));
+        assertEquals("Hello there", test(grid()).getCellText(0, 1));
+
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+
+        assertFalse(send().isEnabled(), "Send is disabled right after sending");
+        test(name()).setValue("B");
+        assertTrue(send().isEnabled(), "Editing re-enables Send");
+    }
+
+    @Test
+    void enterSendsTheForm() {
+        navigate("contact", ContactView.class);
+        fill("Alice", "alice@example.com", "", "Sent with Enter");
+        fireShortcut(Key.ENTER);
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Sent with Enter", test(grid()).getCellText(0, 1));
+    }
+
+    @Test
+    void newestMessageIsFirst_andSurvivesNavigation() {
+        navigate("contact", ContactView.class);
+        fill("Alice", "alice@example.com", "", "First");
+        test(send()).click();
+        fill("Bob", "bob@example.com", "", "Second");
+        test(send()).click();
+
+        assertEquals(2, test(grid()).size());
+        assertEquals("Bob", test(grid()).getCellText(0, 0));
+        assertEquals("Alice", test(grid()).getCellText(1, 0));
+
+        navigate("about", AboutView.class);
+        navigate("contact", ContactView.class);
+
+        assertEquals(2, test(grid()).size());
+        assertEquals("Second", test(grid()).getCellText(0, 1));
+    }
+
+    @Test
+    void emptyForm_leavesWithoutAsking() {
+        navigate("contact", ContactView.class);
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        assertEquals(0, find(Dialog.class).all().size());
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void dirtyForm_asksBeforeLeaving_keepEditing() {
+        navigate("contact", ContactView.class);
+        test(name()).setValue("Alice");
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        Dialog dialog = find(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        test(find(Button.class).withText("Keep editing").single()).click();
+
+        assertTrue(getCurrentView() instanceof ContactView,
+                "Keep editing stays on the contact view");
+        assertEquals("Alice", name().getValue());
+    }
+
+    @Test
+    void dirtyForm_asksBeforeLeaving_discard() {
+        navigate("contact", ContactView.class);
+        test(message()).setValue("Half written");
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        test(find(Button.class).withText("Discard").single()).click();
+
+        assertTrue(getCurrentView() instanceof AboutView,
+                "Discard proceeds to the about view");
+    }
+
+    @Test
+    void dirtyForm_asksOnProgrammaticNavigation() {
+        navigate("contact", ContactView.class);
+        test(phone()).setValue("123");
+        UI.getCurrent().navigate(AboutView.class);
+
+        assertTrue(find(Dialog.class).exists(),
+                "Navigation from anywhere is confirmed");
+        assertTrue(getCurrentView() instanceof ContactView);
+
+        test(find(Button.class).withText("Discard").single()).click();
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+}
